"use client";
import { useState } from "react";
import { ArrowUpRightIcon } from "@phosphor-icons/react";
import { ShimmerButton } from "../magicui/ShimmerButton";
import { DemoFrame } from "../shared/DemoFrame";

export default function Demo() {
  const [ready, setReady] = useState(false);
  return (
    <DemoFrame
      hint={ready ? "Your next idea is ready to begin." : "A little light around the edges."}
    >
      <ShimmerButton onClick={() => setReady(!ready)} shimmerColor="#9bc9ff">
        <span className="relative z-10 flex items-center gap-3 text-sm">
          {ready ? "Start again" : "Start something"}
          <ArrowUpRightIcon size={16} />
        </span>
      </ShimmerButton>
    </DemoFrame>
  );
}

/** Example and adapters: Copyright (c) 2026 NikroZorkin. MIT; licenses/elements.txt. */
import type { ReactNode } from "react";

/** Layout for this example only. The component itself has no catalog dependency. */
export function DemoFrame({
  children,
  className = "",
  hint,
}: {
  children: ReactNode;
  className?: string;
  hint?: string;
}) {
  return (
    <div
      className={`relative flex min-h-[420px] w-full flex-col items-center justify-center gap-7 overflow-hidden p-8 ${className}`}
    >
      {children}
      {hint && (
        <p className="text-center text-xs text-muted-foreground" role="status">
          {hint}
        </p>
      )}
    </div>
  );
}

